          "آرگومان‌های کلیدی شامل key (نام متغیر دسته‌بندی) و value (مقدار عددی) هستند",
          "تسلط بر این توابع برای خواندن، فهمیدن و نگهداری کدهای قدیمی در گیت‌هاب و مقالات ضروری است"
