export const EN_LEVELS: Record<string, Partial<LocalizedLevelData>> = {
  hello: {
    lesson: `### Chapter 1 — Introduction & Hello, R

R is one of the most popular programming languages for data science, statistical computing, and scientific data visualization.

In the interactive R console, any entered expression is evaluated immediately, and the result is printed to the screen:

\`\`\`r
print("Hello, R!")
\`\`\`

Press **Enter** or **Ctrl + Enter** to execute your code.`,
  },
  rstudio: {
    lesson: `### Chapter 2 — RStudio & the Workspace

RStudio is the premier integrated development environment (IDE) for R.
- **Ctrl + Enter**: Run the current line in the console
- **Alt + -**: Automatically insert the assignment operator \`<-\`
- **\`ls()\`**: Returns the names of all active variables and objects residing in the global environment (.GlobalEnv) as a character vector.`,
  },
  numbers: {
    lesson: `### Chapter 3 — Math Operations & Variables

Beyond standard addition and multiplication, R provides specialized arithmetic operators:
- **Integer division (\`%/%\`)**: Discards remainder (\`17 %/% 5\` is 3)
- **Modulo (\`%%\`)**: Computes remainder (\`17 %% 5\` is 2)
- **Power (\`^\`)**: Raises a number to an exponent (\`2^4\` is 16)
- **Assignment (\`<-\`)**: Standard symbol for variable assignment`,
  },
  vectors: {
    lesson: `### Chapter 4 — Vectors & Matrices

Vectors are the fundamental building block in R, created with the \`c()\` combine function.
Matrices are two-dimensional, homogeneous arrays instantiated using \`matrix()\`:

\`\`\`r
mat <- matrix(1:6, nrow = 2, ncol = 3, byrow = TRUE)
\`\`\`

Matrix indexing uses the \`mat[row, col]\` notation starting at index 1.`,
  },
  'data-structures': {
    lesson: `### Chapter 5 — Factors, Data Frames & Lists

- **Factor**: Encodes categorical variables with discrete levels (\`factor()\`).
- **List**: Heterogeneous container storing objects of different types and varying lengths.
- **Data Frame (\`data.frame\`)**: 2D tabular dataset where each column is an equal-length vector with its own type.`,
  },
  'factors-reorder': {
    lesson: `### Chapter 6 — Factors & Categorical Reordering

In R, qualitative data is stored in **factors**. Factors possess an underlying set of \`levels\` that govern how categories appear on plot axes, legends, and which category serves as the baseline reference in regression models.

By default, R sorts factor levels **alphabetically**, which often distorts plots and masks underlying patterns:
\`\`\`r
cities <- factor(c("Tokyo", "Berlin", "London"))
levels(cities) # "Berlin" "London" "Tokyo"
\`\`\`

To present data logically, reorder factors based on a numerical summary (such as median income):
\`\`\`r
ordered_f <- reorder(factor_var, numeric_metric, FUN = median)
\`\`\`

In the tidyverse, \`forcats::fct_reorder()\` provides a streamlined functional pipeline for ggplot2.

#### ⚠️ Common Gotchas:
- **Unused Levels Dropping:** Subsetting or filtering rows does not automatically prune unused factor levels. Use \`droplevels(df)\` to drop stale categories.
- **Regression Baselines:** In \`lm()\`, the first level serves as the reference intercept. Use \`relevel(f, ref = "...")\` to select an interpretable baseline.`,
  },
  'control-flow': {
    lesson: `### Chapter 7 — Control Flow & Vectorization

In R, the vectorized function \`ifelse(test, yes, no)\` evaluates conditions across every element of a vector simultaneously:

\`\`\`r
status <- ifelse(scores >= 50, "pass", "fail")
\`\`\`

Vectorized branching is vastly faster than traditional iterative for-loops.`,
  },
  functions: {
    lesson: `### Chapter 8 — Custom Functions & Apply

Functions are defined with the \`function\` keyword and return the value of the last evaluated expression:

\`\`\`r
cube <- function(x) x^3
\`\`\`

The \`apply\` family (\`sapply\`, \`lapply\`) maps a function across elements of a vector or list without manual loops.`,
  },
  'type-safe-apply': {
    lesson: `### Chapter 9 — Type-Safe Iteration with vapply

In R, the \`apply\` family is central to functional data transformations. However, \`sapply()\` carries a severe liability in production pipelines:
**Silent, unpredictable return-type coercion!**
If an input list is empty, \`sapply\` returns an empty list; if outputs have uniform length, it returns a matrix; otherwise, an atomic vector. This polymorphism is a notorious source of silent runtime failures.

The standard function \`vapply(X, FUN, FUN.VALUE)\` enforces strict type and dimension contracts:
\`\`\`r
vapply(metrics, mean, numeric(1))
\`\`\`
If any iteration produces an unexpected type or dimension, R aborts immediately with an informative error rather than propagating corrupted data downstream.

In tidyverse \`purrr\`, typed functions such as \`map_dbl()\` and \`map_chr()\` uphold this same guarantee.

#### ⚠️ Common Gotchas:
- **FUN.VALUE Template Mismatch:** The template must strictly match the return length of each iteration (e.g., \`numeric(2)\` for two-element outputs like \`range\`).`,
  },
  'import-flat': {
    lesson: `### Chapter 10 — Flat Files & CSV Import

Delimited text files (CSV, TSV) are the most common formats for data exchange.
The \`read.csv()\` function parses comma-delimited text into a structured \`data.frame\`.`,
  },
  'import-excel': {
    lesson: `### Chapter 11 — Inspecting Tabular Data

After importing tabular data, standard functions provide immediate inspection:
- \`nrow()\` / \`ncol()\`: Dimensions of rows and columns
- \`mean()\`: Arithmetic average of numeric vectors
- \`summary()\`: Descriptive 5-number statistics and distributions`,
  },
  'import-db': {
    lesson: `### Chapter 12 — Relational Queries & DB Logic

Filtering records according to logical criteria directly matches the SQL WHERE clause.
In R, the \`subset()\` function filters rows matching compound boolean conditions (\`&\` for AND, \`|\` for OR).`,
  },
  'import-web': {
    lesson: `### Chapter 13 — Web Data & JSON Records

Web services and REST APIs deliver hierarchical records in JSON format.
Vectorized extraction across nested lists allows pulling specific attributes into clean tabular structures.`,
  },
  rectangling: {
    lesson: `### Chapter 14 — Data Rectangling & Hierarchies

Web APIs and NoSQL stores return hierarchical trees of JSON records.
**Data Rectangling** (highlighted by Hadley Wickham in R4DS) is the discipline of flattening nested lists and tree structures into tidy 2D data frames ready for vectorized exploration and modeling:
\`\`\`r
user_table <- do.call(rbind, lapply(raw_records, as.data.frame))
\`\`\`

In the tidyverse, \`tidyr\` provides specialized verbs like \`unnest_wider()\`, \`unnest_longer()\`, and \`hoist()\` to unpack multi-level list-columns.

#### ⚠️ Common Gotchas:
- **Ragged Records with Missing Keys:** If API records have varying fields, naive \`rbind\` fails due to column count discrepancies. Normalize missing fields with default values before binding.`,
  },
  'tidy-data': {
    lesson: `### Chapter 15 — Tidy Data & Missing Values

In Tidy Data:
- Missing observations are represented by the special value \`NA\`.
- Never use \`x == NA\`; always use \`is.na(x)\` to test for missingness.
- The \`na.omit(df)\` function strips all incomplete rows from a dataset.`,
  },
  pivoting: {
    lesson: `### Chapter 16 — Reshaping Data: Pivoting Wide to Long

A foundational tenet of **Tidy Data** in R for Data Science:
1. Each variable forms a column.
2. Each observation forms a row.
3. Each value forms a cell.

Business reports frequently store repeated measurements in wide format (e.g., Q1 and Q2 revenue as column names). For statistical modeling (\`lm\`) and multivariate visualization (\`ggplot2\`), tables must be reshaped into tidy long format:
\`\`\`r
long_df <- reshape(
  wide_df,
  direction = "long",
  varying = c("Q1", "Q2"),
  v.names = "revenue",
  timevar = "quarter",
  times = c("Q1", "Q2"),
  idvar = "dept"
)
\`\`\`

In tidyverse \`tidyr\`, this workflow is performed via \`pivot_longer()\`.

#### ⚠️ Common Gotchas:
- **Homogeneous Data Types:** Columns gathered into a single value column must share compatible data types, or R will coerce them into character strings.`,
  },
  'strings-regex': {
    lesson: `### Chapter 17 — Strings & Regular Expressions

For text cleaning and pattern matching in R:
- \`gsub(pattern, replacement, x)\`: Replace all occurrences of a regular expression pattern
- \`grepl(pattern, x)\`: Test whether a pattern matches
- \`paste()\`: Concatenate strings and vectors`,
  },
  dplyr: {
    lesson: `### Chapter 18 — Data Wrangling & Pipelines

The native pipe operator (\`|>\`):
Passes the left-hand result into the first argument of the right-hand function.
This creates clean, linear, readable data transformation pipelines without deeply nested parentheses:

\`\`\`r
data |> filter(...) |> transform(...)
\`\`\`

#### ⚠️ Common Gotchas:
- **Parentheses required in native pipe:** In the legacy \`%>%\` pipe, writing \`x %>% mean\` was permissible; the native \`|>\` pipe strictly requires function call parentheses (\`x |> mean()\`).`,
  },
  joins: {
    lesson: `### Chapter 19 — Merging & Relational Joins

Combining tables is done with the \`merge()\` function:
- **Left Join**: Setting \`all.x = TRUE\` preserves all rows of the left table and inserts \`NA\` for unmatched rows in the right table.
- **Inner Join**: Default setting of \`merge()\` that keeps only rows present in both tables.

#### ⚠️ Common Gotchas:
- **Row explosion with duplicate keys:** If the joining key column contains non-unique values in either table, merge performs a Cartesian product, multiplying row counts unexpectedly.`,
  },
  'anti-joins': {
    lesson: `### Chapter 20 — Filtering Joins: Anti-Joins & Semi-Joins

In relational data systems, joins divide into two classes:
1. **Mutating Joins:** (e.g. \`inner_join\`, \`left_join\`) which append columns from the secondary table.
2. **Filtering Joins:** Which filter rows of the primary table without altering its column schema:
   - **Semi-Join:** Keeps rows with matching keys in the second table.
   - **Anti-Join:** Keeps rows that have **no** matching key in the second table.

Anti-joins are indispensable for data auditing, discovering orphaned foreign keys, finding churned users, and verifying referential integrity:
\`\`\`r
churned <- subset(all_users, !(id %in% active_users$id))
\`\`\`

In \`dplyr\`, this operation is invoked declaratively with \`anti_join(x, y, by = "id")\`.

#### ⚠️ Common Gotchas:
- **Safe NA Handling with %in%:** The \`%in%\` operator cleanly evaluates \`NA\` values to \`FALSE\`, whereas \`==\` returns \`NA\`, which inadvertently corrupts logical row subsetting.`,
  },
  datetime: {
    lesson: `### Chapter 21 — Dates & Times in R

In R, the \`Date\` class handles calendar dates, while \`POSIXct\` stores timestamps with hours and seconds.
Subtracting two Date objects automatically yields the duration in days (\`difftime\`).

#### ⚠️ Common Gotchas:
- **4-digit vs 2-digit years:** In date formatting, \`%Y\` represents 4-digit years (2026) while \`%y\` represents 2-digit years (26). Confusing them causes century calculation bugs.`,
  },
  'data-table': {
    lesson: `### Chapter 22 — Group Aggregation (Split-Apply-Combine)

The \`aggregate(formula, data, FUN)\` function groups numeric data by categorical factors and computes summary statistics (such as sum or mean) for each group.

#### ⚠️ Common Gotchas:
- **Dropping NA rows by default:** By default, \`aggregate()\` removes rows containing \`NA\` in grouping factors unless \`na.action = na.pass\` is explicitly provided.`,
  },
  'outliers-plots': {
    lesson: `### Chapter 23 — Outliers & Base Plots

- **Interquartile Range (\`IQR\`):** Difference between the 75th and 25th percentiles.
- **Tukey's Outlier Criterion:** Observations below \`Q1 - 1.5*IQR\` or above \`Q3 + 1.5*IQR\` are flagged as statistical outliers.
- **Boxplot (\`boxplot\`):** Visualizes the median, quartiles, and statistical outliers simultaneously.

#### ⚠️ Common Gotchas:
- **Blindly deleting outliers:** Outliers should never be removed without investigation; they often carry the most important signals (such as fraud or sensor malfunction).`,
  },
  regression: {
    lesson: `### Chapter 24 — Linear Regression & Model Diagnostics

R was built from the ground up for statistical modeling and inference.
The \`lm(formula, data)\` function estimates Ordinary Least Squares (OLS) linear regressions:

\`\`\`r
fit <- lm(mpg ~ wt + hp, data = mtcars)
summary(fit)
\`\`\`

- **Coefficients (\`coef\`):** Quantify the marginal effect of each predictor on the target response.
- **R-squared:** Proportion of variation in the response explained by the linear model.

#### ⚠️ Common Gotchas:
- **Correlation is not causation:** Statistical significance does not establish a causal mechanism in real-world data.
- **The R-squared trap:** Adding irrelevant predictors always increases R-squared. In multiple regressions, always evaluate Adjusted R-squared.`,
  },
  hypothesis: {
    lesson: `### Chapter 25 — Hypothesis Testing & Predictions

Hypothesis testing helps distinguish real underlying phenomena from random sample noise.
The \`t.test()\` function compares means across two independent groups (such as automatic vs. manual transmissions).
A **p-value** below 0.05 rejects the null hypothesis at the 95% confidence level.

The \`predict(model, newdata)\` function uses the fitted model to generate forecasts on new observations.

#### ⚠️ Common Gotchas:
- **Column names in \`newdata\`:** The \`newdata\` parameter must be a \`data.frame\` with column names strictly matching the predictors defined in the model formula.`,
  },
  capstone: {
    lesson: `### Chapter 26 — Capstone: End-to-End Data Analysis

Congratulations! You have mastered data wrangling, data structures, relational joins, statistical modeling, and scientific visualization in R.
In this capstone project:
1. Clean missing values from real-world environmental air quality observations.
2. Measure physical correlation between atmospheric temperature and ozone levels.
3. Render a publication-quality scatter plot overlaid with an Ordinary Least Squares regression trendline (\`abline(lm(...))\`).

#### ⚠️ Common Gotchas:
- **Anscombe's Quartet:** Never rely solely on summary metrics or correlation coefficients without inspecting the underlying graphical distribution.`,
  },
  'pkg-anatomy': {
    lesson: `### Chapter 27 — Package Anatomy & The DESCRIPTION File

In R, packages are the standard unit of shareable, reproducible code, data, and documentation.
A canonical R package conforms to strict directory conventions:
- **\`DESCRIPTION\`**: The manifest defining package metadata (Package name, Version, Title, License, and Dependencies).
- **\`NAMESPACE\`**: Declares the public API boundary (exported and imported symbols).
- **\`R/\`**: Directory containing all R source code.
- **\`man/\`**: Documentation manual files generated in \`.Rd\` format.

The \`DESCRIPTION\` file follows the Debian Control Format (DCF) and can be programmatically inspected or generated using base R's \`read.dcf()\` and \`write.dcf()\`.

#### ⚠️ Common Gotchas:
- **Strict Package Naming Rules:** Package names can only contain ASCII letters, numbers, and periods (\`.\`). They must start with a letter, and hyphens (\`-\`) or underscores (\`_\`) are strictly forbidden on CRAN.
- **Semantic Versioning:** Always use 3-part semantic versioning (e.g. \`0.1.0\`) to communicate patch, minor, and major API revisions clearly.`,
  },
  'pkg-deps': {
    lesson: `### Chapter 28 — Package Dependencies: Imports vs. Suggests

Declaring dependencies in the \`DESCRIPTION\` file is a fundamental engineering discipline:
- **\`Imports\`**: Packages essential at runtime. They are installed automatically whenever a user installs your package.
- **\`Suggests\`**: Optional packages needed only for unit tests, vignettes, or optional specialized functions.

#### The Golden Rule of Package Code:
**Never call \`library()\` or \`require()\` inside package functions!** Calling \`library()\` mutates the user's global search path and immediately triggers an ERROR in \`R CMD check\`.

Instead, use explicit qualified calls like \`pkg::fun()\` and guard optional dependencies using:
\`\`\`r
if (!requireNamespace("pkg", quietly = TRUE)) {
  stop("Package 'pkg' is required for this function.")
}
\`\`\`

#### ⚠️ Common Gotchas:
- **The Depends Trap:** The legacy \`Depends\` field attaches the entire foreign package to the user's search path, risking function masking. Modern best practice is to always specify \`Imports\`.`,
  },
  'pkg-code': {
    lesson: `### Chapter 29 — Package Code & Side Effects (on.exit)

A package function must be a courteous guest in the user's R session!
It should never permanently modify the global environment (\`.GlobalEnv\`), change working directories (\`setwd()\`), or alter options (\`options()\`) or graphics parameters (\`par()\`) without guaranteed restoration.

The idiomatic R solution is \`on.exit()\`:
\`\`\`r
my_fn <- function(x) {
  old_par <- par(mfrow = c(1, 2))
  on.exit(par(old_par), add = TRUE)
  # Plotting operations...
}
\`\`\`
R guarantees that the expression registered in \`on.exit()\` will execute when the function terminates, even if an error is raised midway.

#### ⚠️ Common Gotchas:
- **Omitting \`add = TRUE\`:** If you forget \`add = TRUE\`, subsequent \`on.exit()\` calls overwrite earlier handlers instead of chaining with them. Always write \`on.exit(..., add = TRUE)\`.`,
  },
  'pkg-roxygen': {
    lesson: `### Chapter 30 — Documentation with roxygen2

In modern R packages, documentation lives directly above function definitions in special comment blocks prefixed with \`#'\`:

\`\`\`r
#' Normalize a numeric vector to [0, 1]
#'
#' @param x Input numeric vector
#' @return Scaled vector bounded between 0 and 1
#' @export
#' @examples
#' normalize_vec(c(10, 20, 30))
normalize_vec <- function(x) { ... }
\`\`\`

Running \`devtools::document()\` parses these roxygen blocks to generate \`.Rd\` files in \`man/\` and update \`NAMESPACE\` exports automatically.

#### ⚠️ Common Gotchas:
- **Missing \`@export\` Tag:** If you omit \`@export\`, the function remains internal (private). Users will not be able to call it after \`library(pkg)\` unless they use the internal triple colon operator (\`pkg:::fun\`).`,
  },
  'pkg-namespace': {
    lesson: `### Chapter 31 — NAMESPACE & Information Hiding

The \`NAMESPACE\` file enforces encapsulation by managing two interfaces:
1. **Exports (\`export\`):** Public functions made directly accessible to consumers when the package is attached.
2. **Imports (\`importFrom\`):** Foreign functions your package borrows from other packages.

This separation prevents name collisions. If another library also defines a function with the same name, your package continues to resolve its own internal dependencies reliably.

#### ⚠️ Common Gotchas:
- **Blind \`import(pkg)\` Directives:** Never import an entire package blindly with \`import(pkg)\`. This pollutes your internal namespace with hundreds of identifiers. Always use targeted \`importFrom(pkg, fun1, fun2)\`.`,
  },
  'pkg-testing': {
    lesson: `### Chapter 32 — Unit Testing with testthat

Unit testing is the foundation of software reliability in R.
Tests are organized under \`tests/testthat/\` using the \`testthat\` package:
- **\`expect_equal(actual, expected)\`**: Tests value equality within numerical floating-point tolerances.
- **\`expect_error(expr)\`**: Asserts that invalid inputs cleanly throw informative exceptions.
- **\`expect_true(condition)\`**: Verifies boolean invariants.

Running **Ctrl + Shift + T** or \`devtools::test()\` executes your entire test suite in seconds, guarding against regression bugs.

#### ⚠️ Common Gotchas:
- **Testing with \`==\` in Unit Tests:** Never use \`expect_true(val == 0.3)\`! Machine precision differences across OS platforms will cause random CI test failures. Always use \`expect_equal()\`.`,
  },
  'pkg-data': {
    lesson: `### Chapter 33 — Package Data & Extdata Assets

R packages can distribute data in two canonical ways:
1. **Curated Datasets (\`data/\`):** Binary \`.rda\` datasets created via \`usethis::use_data()\`, accessible immediately via \`data(mydata)\`.
2. **External Raw Files (\`inst/extdata/\`):** Unaltered CSV, JSON, or template files for demonstrating parsing pipelines.

During installation, everything inside \`inst/\` is promoted to the installed package root directory. Files are resolved portably using \`system.file()\`:
\`\`\`r
path <- system.file("extdata", "sample_cars.csv", package = "mypkg")
\`\`\`

#### ⚠️ Common Gotchas:
- **Hardcoding \`inst\` in Paths:** Never write \`system.file("inst/extdata", ...)\`! The \`inst/\` prefix is discarded upon package installation.`,
  },
  'pkg-check': {
    lesson: `### Chapter 34 — Quality Control & CRAN Readiness (R CMD check)

\`R CMD check\` (run via \`devtools::check()\`) is the legendary automated quality gate of the R ecosystem.
It executes over 50 rigorous automated checks:
- Strict consistency between function arguments and \`roxygen2\` documentation.
- Absence of unauthorized \`library()\` calls.
- Full execution of all unit tests and reproducible examples without error.
- Zero undeclared global variables.

Diagnostics are reported in three tiers:
- **ERROR**: Critical flaw preventing package installation or building.
- **WARNING**: Serious issue violating CRAN policy.
- **NOTE**: Minor advisory notes.

The hallmark of a production-ready package is achieving **0 errors | 0 warnings | 0 notes**.

#### ⚠️ Common Gotchas:
- **Tidyverse Columns & R CMD check Notes:** Non-standard evaluation (NSE) in functions like \`subset()\` or \`dplyr::filter()\` flags column names as undefined global variables! Fix this by declaring them in \`R/globals.R\` via \`utils::globalVariables(c("col1", "col2"))\`.`,
  },
  "tidy-tibble": {
    lesson: "### Chapter 35 — Modern Data Frames with tibble\n\nThe `tibble` package is the foundational tabular data structure of the `tidyverse`, offering a modernized, stricter reimplementation of base R's `data.frame`.\n\nKey design differences:\n1. **No Partial Matching:** Base data frames silently match `df$x` to column `xyz`. Tibbles disable partial matching entirely, throwing an informative warning.\n2. **No Silent Dimension Dropping:** Base data frames unexpectedly drop from a 2D table to a 1D vector when subsetting a single column via `df[, 1]`. Tibbles always return a tibble.\n3. **Optimized Console Printing:** Tibbles print only the first 10 rows and explicitly show data types (`<dbl>`, `<chr>`, `<int>`) in the column header.\n\n#### ⚠️ Common Gotchas:\n- **Converting Existing Data:** Use `as_tibble()` to convert existing matrices or data frames. The `tibble()` constructor is meant for building new columns from scratch.",
  },
  "tidy-dplyr": {
    lesson: "### Chapter 36 — Fast Data Manipulation with dplyr\n\nThe `dplyr` package provides a consistent grammar of data manipulation in R, organized around five fundamental verbs:\n- **`filter()`**: Pick rows matching logical criteria.\n- **`select()`**: Pick or rename specific columns.\n- **`mutate()`**: Create new calculated columns from existing variables.\n- **`arrange()`**: Reorder rows ascending or descending via `desc()`.\n- **`summarise()`**: Collapse multiple values into a single summary metric.\n\nChaining these verbs with the native pipe operator (`|>`) creates highly expressive, self-documenting data pipelines.\n\n#### ⚠️ Common Gotchas:\n- **Assignment vs Equality in `filter`:** Always use `==` inside `filter()` for logical comparisons, never the single assignment operator `=`.\n- **Function Masking:** The base `stats` package also provides a `filter()` function. If conflicting, explicitly call `dplyr::filter()`.",
  },
  "tidy-ggplot2": {
    lesson: "### Chapter 37 — Grammar of Graphics with ggplot2\n\n`ggplot2` implements Leland Wilkinson's Grammar of Graphics, decomposing statistical charts into independent, stackable layers:\n1. **Data:** A tidy `data.frame` or `tibble`.\n2. **Aesthetic Mappings (`aes`):** Connecting dataset variables to visual dimensions (x, y, color, size, shape).\n3. **Geometries (`geom_*`):** Visual representation of data points (`geom_point`, `geom_line`, `geom_col`).\n4. **Labels & Themes (`labs`, `theme`):** Polishing titles, axes, and visual styling.\n\nLayers are combined modularly using the `+` operator.\n\n#### ⚠️ Common Gotchas:\n- **Pipes vs Plus Operator:** Layers in ggplot2 are combined with `+`, never with the pipe operator `|>`!\n- **Fixed Constants Inside `aes()`:** To set a constant color like blue for all points, pass `color = \"blue\"` to `geom_point()`, outside of `aes()`.",
  },
  "tidy-tidyr": {
    lesson: "### Chapter 38 — Modern Tidy Reshaping with tidyr\n\nTidy datasets follow three universal rules:\n1. Each variable must have its own column.\n2. Each observation must have its own row.\n3. Each value must have its own cell.\n\nThe `tidyr` package provides modern tools for table reshaping:\n- **`pivot_longer()`**: \"Lengthens\" wide tables by gathering column headers into key-value observation pairs.\n- **`pivot_wider()`**: \"Widens\" long records into tabular reporting matrices.\n\n#### ⚠️ Common Gotchas:\n- **Legacy Functions:** Avoid deprecated `gather()` and `spread()` functions in modern code. Always use `pivot_longer()` and `pivot_wider()`.",
  },
  "tidy-stringr": {
    lesson: "### Chapter 39 — Consistent String Manipulation with stringr\n\nBase R text functions (`grep`, `sub`, `regexpr`) have notoriously inconsistent argument order.\nThe `stringr` package solves this with a cohesive, predictable API:\n1. All functions share the common `str_` prefix, facilitating IDE autocomplete.\n2. The input character vector (`string`) is **always the first argument**, ensuring natural pipe chaining with `|>`.\n3. Predictable propagation of missing values (`NA`).\n\nCore verbs:\n- **`str_detect(string, pattern)`**: Returns a logical vector of matches.\n- **`str_replace_all(string, pattern, replacement)`**: Replaces all regex matches across vectors.\n- **`str_extract(string, pattern)`**: Extracts first matching substring.\n\n#### ⚠️ Common Gotchas:\n- **Escaping Regex Metacharacters:** Because backslashes are string escape characters in R, regex metacharacters require double escaping (e.g. `\\\\d+` for digits).",
  },
  "tidy-forcats": {
    lesson: "### Chapter 40 — Categorical Data Wrangling with forcats\n\nFactors represent categorical data with fixed, predefined levels.\nBy default, R sorts factor levels alphabetically, which is rarely optimal for plots or statistical models.\nThe `forcats` package provides specialized helpers for factor manipulation:\n- **`fct_reorder(.f, .x, .fun)`**: Reorders factor levels according to a summary of another numeric variable.\n- **`fct_rev(f)`**: Inverts the order of factor levels (ideal for horizontal bar charts).\n- **`fct_lump_n(f, n)`**: Collapses infrequent factor levels into a consolidated `Other` category.\n\n#### ⚠️ Common Gotchas:\n- **Factor to Numeric Pitfall:** Calling `as.numeric(factor)` returns internal integer codes, not character values! Always use `as.numeric(as.character(factor))`.",
  },
  "tidy-lubridate": {
    lesson: "### Chapter 41 — Date-Time Parsing & Rounding with lubridate\n\nWorking with dates in base R required memorizing complex format codes like `\"%Y-%m-%d %H:%M:%S\"`.\nThe `lubridate` package makes temporal data intuitive:\n- **Format-Free Parsers:**\n  - `ymd(\"2026-03-15\")`: Year, Month, Day\n  - `dmy(\"15-03-2026\")`: Day, Month, Year\n- **Time Rounding:**\n  - `floor_date(x, unit = \"month\")`: Snaps timestamp to beginning of month.\n  - `ceiling_date(x, unit = \"week\")`: Snaps timestamp to start of following week.\n- **Component Extractors:** `year()`, `month()`, `wday()`\n\n#### ⚠️ Common Gotchas:\n- **Periods vs Durations:** lubridate strictly distinguishes between calendar-aware `Periods` (like 1 month, varying from 28 to 31 days) and physical `Durations` (exact seconds).",
  },
  "tidy-purrr": {
    lesson: "### Chapter 42 — Functional Programming & Iteration with purrr\n\nIn professional R programming, imperative `for` loops are replaced by functional higher-order functions.\nBase R's `sapply()` is notoriously dangerous because its output type depends on runtime data contents, returning vectors, matrices, or lists unpredictably.\nThe `purrr` package enforces strict type stability:\n- **`map(.x, .f)`**: Always returns a `list`.\n- **`map_dbl(.x, .f)`**: Guarantees a `double` numeric vector or fails immediately.\n- **`map_chr(.x, .f)`**: Guarantees a `character` vector.\n- **`map_lgl(.x, .f)`**: Guarantees a `logical` vector.\n\n#### ⚠️ Common Gotchas:\n- **Silent sapply Failures:** Never use `sapply()` in production code. Use `purrr` typed maps or base `vapply()` to guarantee type safety.",
  },
  "adv-memory": {
    lesson: "### Chapter 43 — Names, Values & Memory Semantics\n\nUnderstanding how R binds names to values is the cornerstone of advanced R programming:\n\n1. **Copy-on-Modify:**\nWhen running `y <- x`, R does not duplicate memory. Both names point to the same physical memory buffer. Only upon mutation (`y[1] <- 99`) does R duplicate the data.\n\n2. **Modify-in-Place (Environments):**\nEnvironments follow reference semantics. Mutating a property on any alias modifies the original environment in-place without copying.\n\n#### ⚠️ Common Gotchas:\n- **Hidden Copies in Loops:** Reassigning a column of a large data frame inside a loop causes quadratic memory churn as the whole table is cloned on each iteration.",
  },
  "adv-environments": {
    lesson: "### Chapter 44 — Environments, Scoping & Closures\n\nFunctions in R bind to their enclosing environment, forming a closure that encapsulates state:\n- **Function Factories:** Functions that manufacture and return configured functions.\n- **Super-assignment (`<<-`):** Modifies existing bindings in parent environments rather than creating a local variable.\n\nThis pattern allows stateful accumulators, rate-limiters, and memoization without polluting the global environment.\n\n#### ⚠️ Common Gotchas:\n- **Unintended Global Bindings:** If the target identifier is not found in any ancestor environment, `<<-` creates it in the `.GlobalEnv`, causing unexpected global side effects.",
  },
  "adv-conditions": {
    lesson: "### Chapter 45 — Advanced Conditions & Error Handling\n\nR's condition system allows robust, typed exception handling using S3 condition objects:\n- **Custom S3 Conditions:** Subclassing `error` and `condition` allows callers to catch specific issue types programmatically without fragile regex string-matching on error messages.\n- **Call Context:** Attaching the active call and diagnostic metadata directly to the condition list facilitates post-mortem inspection.\n\n#### ⚠️ Common Gotchas:\n- **String-matching Error Messages:** Never parse `e$message` in `tryCatch()`. Always rely on distinct condition classes for reliable error categorization.",
  },
  "adv-s3": {
    lesson: "### Chapter 46 — S3 Object-Oriented Programming\n\nS3 is R's foundational, functional object-oriented programming paradigm:\n- **Generics & Method Dispatch:** A generic function defines the interface via `UseMethod(\"generic_name\")`, and R dispatches execution to `generic_name.class_name()` based on the S3 class vector of the first argument.\n- **Constructors:** Clean S3 designs utilize a low-level `new_classname()` constructor that validates inputs and returns a structured list with an assigned class attribute.\n\n#### ⚠️ Common Gotchas:\n- **Dots in Function Names:** Avoid dots in normal function identifiers (e.g. `save.data`); S3 dispatch may misinterpret them as methods for generic `save` on class `data`.",
  },
  "adv-r6": {
    lesson: "### Chapter 47 — Encapsulated OOP with R6\n\nUnlike S3's functional approach, **R6** delivers encapsulated object-oriented programming with mutable reference semantics:\n- **Methods belong to objects:** Accessed via `obj$method()` syntax.\n- **Reference Semantics:** Modifying an R6 instance updates the object in-place without triggering copy-on-modify.\n- **Method Chaining:** Returning `invisible(self)` enables fluid chaining patterns (`acc$add(10)$add(5)`).\n\n#### ⚠️ Common Gotchas:\n- **Assignment Does Not Clone:** Writing `b <- a` merely creates a second reference to the exact same instance in memory. Always use `a$clone(deep = TRUE)` for independent copies.",
  },
  "adv-expressions": {
    lesson: "### Chapter 48 — Expressions, AST & Code as Data\n\nR is homoiconic: code is represented as first-class data structures known as Abstract Syntax Trees (ASTs):\n- **Capturing Code:** `quote()` returns unevaluated expressions (calls, symbols, and constants).\n- **Deconstructing Calls:** A call acts like a list where element `[[1]]` is the function symbol and subsequent elements are arguments.\n- **Dynamic Metaprogramming:** You can inspect, modify, and evaluate expressions at runtime using `eval()`.\n\n#### ⚠️ Common Gotchas:\n- **Symbols vs Characters:** A symbol (`quote(x)`) represents an unquoted variable name, whereas `\"x\"` is a character constant. Treating symbols as strings causes evaluation failures.",
  },
  "adv-quasiquote": {
    lesson: "### Chapter 49 — Quasiquotation & Non-Standard Evaluation\n\nNon-Standard Evaluation (NSE) and Data Masking allow functions to evaluate arguments in custom scopes:\n- **`substitute(expr)`:** Captures the unevaluated R code passed to an argument.\n- **`eval(expr, envir = df, enclos = parent.frame())`:** Evaluates the expression using columns of `df` as first-class variables, falling back to the calling environment for foreign identifiers.\n\n#### ⚠️ Common Gotchas:\n- **Ambiguity between Data and Env Variables:** If an external variable shares a name with a table column, data masking resolves to the column. Use explicit qualifiers (`.env$x` vs `.data$x`) to prevent bugs.",
  },
  "adv-profiling": {
    lesson: "### Chapter 50 — Benchmarking & Memory Optimization\n\nWriting high-performance R code requires understanding how memory allocation affects algorithmic complexity:\n- **The Growing Vector Trap:** Calling `vec <- c(vec, new_item)` inside a loop reallocates and copies the entire array every iteration, degrading performance to quadratic $O(N^2)$ time.\n- **Pre-allocation:** Allocating the destination vector upfront with `numeric(n)` or `vector(\"list\", n)` achieves optimal linear $O(N)$ execution.\n- **Native Vectorization:** Compiled C primitives in R outpace interpreted loops by orders of magnitude.\n\n#### ⚠️ Common Gotchas:\n- **Ignoring Existing Vectorized Primitives:** Before writing explicit loops, check if a vectorized primitive (such as `(1:n)^2` or `colSums()`) solves the task natively.",
  },
  "tidyr-separate-unite": {
    lesson: "### Chapter 51 — Column Splitting & Combining with tidyr\n\nData often packs multiple measurements into a single compound string:\n- **`separate(data, col, into, sep)`:** Splits a delimited column into distinct variables.\n- **`unite(data, col, ..., sep)`:** Glues multiple columns together into a single identifier.\n\nModern tidyr also features `separate_wider_delim()` and `separate_wider_regex()` for strict programmatic safety.\n\n#### ⚠️ Common Gotchas:\n- **Mismatched Split Lengths:** When rows contain variable numbers of delimiters, use `extra = \"merge\"` or `fill = \"right\"` to prevent dropped fragments.",
  },
  "tidyr-gather-spread": {
    lesson: "### Chapter 52 — Classic Reshaping with gather() & spread()\n\nBefore `pivot_longer()` and `pivot_wider()` arrived, `gather()` and `spread()` formed the backbone of tidy data transformations:\n- **`gather(data, key, value, ...)`:** Gathers wide columns into key-value pairs.\n- **`spread(data, key, value)`:** Spreads long key-value observations across columns.\n\nUnderstanding their exact mechanics is essential for maintaining production codebases and consulting legacy R scripts.\n\n#### ⚠️ Common Gotchas:\n- **Bare Arguments:** The `key` and `value` names are passed as unquoted symbols, which could clash with column names in complex pipelines.",
  },
  "tidy-hms": {
    lesson: "### Chapter 53 — Time of Day & Durations with hms\n\nMany analytical workflows require pure **time of day** independent of any calendar date:\n- **The `hms` class:** Stores elapsed seconds since midnight and renders cleanly as `HH:MM:SS`.\n- **Interval Arithmetic:** Subtracting two `hms` objects yields clean physical durations without timezone or leap-second interference.\n\n#### ⚠️ Common Gotchas:\n- **Attaching Arbitrary Dates:** Using `POSIXct` for time of day silently prepends today's date, causing bugs when calculating recurring daily deltas.",
  },
  "import-readxl": {
    lesson: "### Chapter 54 — Excel Worksheets Import with readxl\n\nExcel workbooks (.xlsx, .xls) are ubiquitous in enterprise environments. The `readxl` package reads them natively without Java or external dependencies:\n- **`excel_sheets(path)`:** Discovers all available worksheet tab names.\n- **`read_excel(path, sheet = ..., range = ...)`:** Imports data directly into a tidy tibble.\n\n#### ⚠️ Common Gotchas:\n- **Merged Header Cells:** Spreadsheets often include corporate titles in rows 1–3. Use `skip = 3` or `range = cell_limits(...)` to skip metadata headers.",
  },
  "data-rodbc": {
    lesson: "### Chapter 55 — Database Queries with DBI & RODBC\n\nEnterprise data architectures store records in relational SQL databases. The **DBI** interface provides a standardized protocol across drivers:\n- **Connection Lifecycle:** `dbConnect()` connects, `dbGetQuery()` fetches tabular records directly, and `dbDisconnect()` terminates sockets cleanly.\n\n#### ⚠️ Common Gotchas:\n- **Leaking Connections:** Unclosed database handles exhaust server connection pools. Always pair connections with `on.exit(dbDisconnect(conn), add = TRUE)`.",
  },
  "prog-r4": {
    lesson: "### Chapter 56 — Modern R 4.x Syntax & Features\n\nR 4.x introduced transformational language modernizations:\n- **The Native Forward Pipe (`|>`):** Baked directly into the R 4.1+ grammar, operating with zero external package dependencies.\n- **Shorthand Lambdas (`\\(x)`):** Concise syntactic sugar replacing verbose `function(x)` declarations.\n- **Raw String Literals (`r\"(...)\"`):** Eliminates double-escaped backslashes in regex.\n- **`stringsAsFactors = FALSE`:** Made the permanent default in R 4.0.0, eliminating a historic pitfall.\n\n#### ⚠️ Common Gotchas:\n- **Mandatory Parentheses:** Unlike magrittr's `%>%`, the native pipe requires explicit parentheses around function calls (`x |> mean()`).",
  },
  "adv-s7": {
    lesson: "### Chapter 57 — Unified Object-Oriented Programming with S7\n\nFor decades, R developers balanced between S3 (informal, no property type enforcement) and S4 (verbose, steep learning curve).\nDeveloped collaboratively by the R Consortium (R Core & Posit), **S7** represents the unified future of R OOP:\n- **`new_class()`:** Explicit class schemas with strictly typed properties and automatic construction validation.\n- **`new_generic()` & `method()`:** First-class polymorphic dispatch without string-munging conventions.\n\n#### ⚠️ Common Gotchas:\n- **Type Invalidation:** In S7, assigning an incompatible type to a declared property triggers an immediate validation failure rather than silently corrupting downstream calculations.",
  },
  "repro-rmarkdown": {
    lesson: "### Chapter 58 — Reproducible Reporting with R Markdown\n\nReproducibility is the gold standard of scientific computing. R Markdown merges narrative documentation with live R calculations:\n- **YAML Frontmatter:** Configures title, author, and output targets (HTML, PDF, Word).\n- **Code Chunks:** Executable blocks bounded by ````{r} ... ````.\n- **Chunk Options:** `echo = FALSE` (hide code from readers), `eval = TRUE` (execute calculations), `message = FALSE`, `warning = FALSE`.\n- **Inline Code:** Embedding dynamic calculations directly into sentences via ```` `r expr` ````.\n\n#### ⚠️ Common Gotchas:\n- **Clean Environment During Rendering:** Running `rmarkdown::render()` executes in a fresh, isolated background process. Everything your report depends on must be explicitly loaded in the document itself.",
  },
};

FA_LEVELS['appendix'] = FA_LEVELS['capstone'];
DE_LEVELS['appendix'] = DE_LEVELS['capstone'];
EN_LEVELS['appendix'] = EN_LEVELS['capstone'];

export function localizeLevel(level: LevelDef, locale: Locale): LevelDef {
  if (locale === 'en') {
    const enLesson = EN_LEVELS[level.id]?.lesson;
    if (enLesson) {
      return {
        ...level,
        lesson: enLesson,
      };
    }
    return level;
  }

  const dictionary = locale === 'fa' ? FA_LEVELS : locale === 'de' ? DE_LEVELS : null;
  const copy = dictionary ? dictionary[level.id] : null;
  if (!copy) {
    return level;
  }

  const checks = level.checks.map((chk, i) => ({
    ...chk,
    label: copy.checksLabels && copy.checksLabels[i] ? copy.checksLabels[i] : chk.label,
  }));

  return {
    ...level,
    title: copy.title || level.title,
    brief: copy.brief || level.brief,
    hint: copy.hint || level.hint,
    lesson: copy.lesson || level.lesson,
    learning: copy.learning || level.learning,
    fieldNotes: copy.fieldNotes || level.fieldNotes,
    checks,
  };
}
